import{_ as t,c as o,o as s,ae as n}from"./chunks/framework.Bi6zybwU.js";const h=JSON.parse('{"title":"Responsive Table Design","description":"Responsive Table Design","frontmatter":{"title":"Responsive Table Design","description":"Responsive Table Design"},"headers":[],"relativePath":"guide/drag-drop-settings/responsive-table-design.md","filePath":"guide/drag-drop-settings/responsive-table-design.md"}'),a={name:"guide/drag-drop-settings/responsive-table-design.md"};function i(r,e,l,d,p,b){return s(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="responsive-table-design" tabindex="-1">Responsive Table Design <a class="header-anchor" href="#responsive-table-design" aria-label="Permalink to &quot;Responsive Table Design&quot;">​</a></h1><p>When it comes to design and UX, responsiveness is the first thing that comes to mind. It’s important to ensure a responsive table design so that the content is visible and readable. Ninja Tables gives you control of your table’s responsiveness, so you don&#39;t have to worry about your tables fitting into different device screens. You can find this option on the leftmost side of the Table Editor and see the responsiveness setting is turned on by default. <img src="https://ninjatables.com/wp-content/uploads/2023/08/responsiveness-1024x428.png" alt="responsiveness"></p><h2 id="properties-of-responsive-table-design" tabindex="-1">Properties of Responsive Table Design <a class="header-anchor" href="#properties-of-responsive-table-design" aria-label="Permalink to &quot;Properties of Responsive Table Design&quot;">​</a></h2><table tabindex="0"><thead><tr><th><strong>Scope</strong></th><th><strong>Option Name</strong></th><th><strong>Type</strong></th></tr></thead><tbody><tr><td><strong>General</strong></td><td>Enable Responsive Table</td><td>Toggle on or off</td></tr><tr><td><strong>Mode Options</strong></td><td>Mobile</td><td>Toggle, dropdown, numeric</td></tr><tr><td></td><td>Tablet</td><td>Toggle, dropdown, numeric</td></tr><tr><td></td><td>Desktop</td><td>Toggle, dropdown, numeric</td></tr><tr><td><strong>Responsive Settings</strong></td><td>Mobile</td><td>Numeric &amp; radio button</td></tr><tr><td></td><td>Tablet</td><td>Numeric &amp; radio button</td></tr></tbody></table><h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><p>Enable the table to be responsive by toggling the button on. <img src="https://ninjatables.com/wp-content/uploads/2023/08/Responsivenss-of-a-table-1024x408.png" alt="Responsivenss of a table"></p><h3 id="mode-options" tabindex="-1">Mode Options <a class="header-anchor" href="#mode-options" aria-label="Permalink to &quot;Mode Options&quot;">​</a></h3><p><strong>Mobile</strong> <strong>and Tablet</strong>: From here, you can customize the responsiveness on mobile and tablet. Both the options have the same customization directions. <img src="https://ninjatables.com/wp-content/uploads/2023/08/Enable-responsiveness-on-mobile-1024x590.png" alt="Enable table responsiveness on mobile"></p><ul><li>Disable Breakpoint will only work when the &quot;Enable Responsive Table&quot; mode is toggled on.</li><li>Cell Stack Direction works when you turn off &quot;Disable Breakpoint&quot; and change the direction of cells stacking as rows or columns.</li><li>Toggle the &quot;Top Row as Header&quot; option.</li><li>Control the number of Items Per Header.</li><li>Select Group Separator. <strong>Desktop</strong>: This is where you can change the header and row position for a desktop view of the table. <img src="https://ninjatables.com/wp-content/uploads/2023/08/table-responsiveness-of-desktop-1024x418.png" alt="table responsiveness of desktop"></li></ul><h3 id="responsive-settings" tabindex="-1">Responsive Settings <a class="header-anchor" href="#responsive-settings" aria-label="Permalink to &quot;Responsive Settings&quot;">​</a></h3><p>You can change Cell Padding and Table Alignment for mobile and tablets the same way. <img src="https://ninjatables.com/wp-content/uploads/2023/08/table-responsiveness-on-mobile-and-tablet-1024x474.png" alt="table responsiveness on mobile and tablet"> For example, here&#39;s the same table as mobile responsive with its top row as a header, 1 item per header, and &quot;Rows&quot; for Cell Stack Direction. <img src="https://ninjatables.com/wp-content/uploads/2023/08/Mobile-responsive-table-1024x501.png" alt="Mobile responsive table"> And we can also show you another responsive table on a tablet that has the top row as its header, cell stack direction &quot;column&quot;, and 1 item per header. <img src="https://ninjatables.com/wp-content/uploads/2023/08/Responsive-table-on-tablets-1024x463.png" alt="Responsive table on tablets"></p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>A responsive table design is a must to keep your audience engaged. Since everyone is now a mobile-user, you can&#39;t deny them a good UX. Make your data tables responsive for all devices. Let us know your thoughts.</p>',13)])])}const c=t(a,[["render",i]]);export{h as __pageData,c as default};
